                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Father name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Trade/company name</th>
                <th className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">Pan No.</th>
