                <tr><td colSpan={8} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No IT records found</td></tr>
              ) : (
                filteredClients.map((client, idx) => {
                  const tradeOrCompany = client.itProfile?.incomeType === 'Salary' 
                    ? client.itProfile?.companyName 
                    : client.tradeName;

                  return (
                    <tr key={client.id} className={`group transition-all ${idx % 2 === 0 ? 'bg-white' : 'bg-slate-50/40 hover:bg-emerald-50/30'}`}>
                      <td className="px-4 py-5"><span className="text-xs font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</span></td>
                      <td className="px-4 py-5">
                        <p className="text-sm font-black text-slate-900 leading-tight truncate max-w-[180px] uppercase">{client.legalName}</p>
                      </td>
                      <td className="px-4 py-5">
                        <p className="text-xs font-bold text-slate-500 uppercase truncate max-w-[160px]">{client.itProfile?.fatherName || '---'}</p>
                      </td>
                      <td className="px-4 py-5">
                        <p className="text-xs font-black text-slate-700 truncate max-w-[160px] uppercase">{tradeOrCompany || '---'}</p>
                      </td>
                      <td className="px-4 py-5 whitespace-nowrap">
                         <span className="text-[11px] font-black text-emerald-600 font-mono tracking-widest uppercase">{client.itProfile?.pan}</span>
                      </td>
                      <td className="px-4 py-5 whitespace-nowrap">
                         <span className="text-[11px] font-black text-slate-600 tracking-wider">{client.mobile || '---'}</span>
                      </td>
                      <td className="px-4 py-5 whitespace-nowrap">
                         <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${
